import json
F='/home/claude/ac-mdcu/parts/fill/l05_r05.json'
d=json.load(open(F))
def S(n,**kw):
  q=d[str(n)]
  for k,v in kw.items():
    if k=='wrong':
      for c,t in v.items(): q['wrong'][c]=t
    else: q[k]=v

S(41,
 interp="หญิงวัยกลางคนมีแผลที่แก้มซึ่งเป็นบริเวณที่ความสวยงามสำคัญที่สุด ถูกปิดด้วย vertical mattress → ถามข้อเสียด้านความสวยงามหลักของวิธีนี้ · ต้องรู้ว่า vertical mattress ทำอะไรได้ดี (eversion) และแลกมาด้วยอะไร (รูเข็มบนผิวมากขึ้นเป็นสองเท่า)",
 why="vertical mattress เข้าและออกผิวสองรอบต่อเข็ม (วงไกล far-far + วงใกล้ near-near) จึงมี<b>รูเข็ม 4 รูต่อ 1 เข็ม</b> แทน 2 รูแบบ simple · วงไหมที่อยู่บนผิวยาวกว่าและรัดผิวมากกว่า ถ้าทิ้งไว้นานจะเกิดรอยเข็มแบบรางรถไฟชัด · กลไกคือ epithelium งอกเข้าไปตามรูไหมเป็นท่อ (suture tract) ยิ่งทิ้งไหมนานยิ่งกลายเป็นจุดแผลเป็นถาวร และถ้าผูกแน่นจนแผลบวม วงไหมจะกดผิวเป็นรอยขวางแนวแผล · แลกกับข้อดีคือ eversion ที่ดีกว่า · ที่หน้าจึงใช้เฉพาะจุดที่ขอบม้วนเข้าจริง ผูกพอให้ขอบชน และตัดไหมให้เร็ว (ราว 5 วัน) หรือเลือก simple ร่วมกับไหมชั้น dermis แทน · สไลด์หน้า 11 <b>Stitch marks</b> · ลายมือ <b>\"= เห็น 4 รู → น่าเกลียดกว่าเดิม -o-\"</b>",
 trap="A คือปัญหาที่ vertical mattress ใช้แก้ ไม่ใช่ปัญหาที่มันก่อ — คนที่จำแค่คำว่า eversion มักสับสนทิศ · แยกโดยจำคู่บนสไลด์: ข้อดี Better eversion · ข้อเสีย Stitch marks จากรูเข็ม 4 รูต่อ 1 เข็ม",
 summary=[
  "<b>Vertical Mattress</b>: Better eversion · ข้อเสีย <b>Stitch marks</b>",
  "ลายมือ: <b>เห็น 4 รู → น่าเกลียดกว่าเดิม</b>",
  "ลายมือ: เกิดมาเพื่อ control wound edge eversion",
  "Far ราว 1 cm · near ราว 2 mm ในแนวเดียวกัน (ลายมือบนรูป)",
  "รอยเข็มชัดขึ้นเมื่อ: ทิ้งไหมนาน ผูกแน่นจนบวม ไหมเส้นใหญ่ · หน้าตัดไหมราว 5 วัน ลำตัว 7–10 วัน แขนขา 10–14 วัน",
  "ลดรอยเข็ม: ใช้เฉพาะจุดที่ขอบม้วนเข้า หรือใช้ simple ร่วมกับไหมชั้น dermis"
 ])

S(42,
 why="vertical mattress: เข็มแรกเข้า<b>ไกลจากขอบราว 1 cm</b> ลงลึกถึง dermis ล่างข้ามไปออกอีกฝั่งที่ระยะเท่ากัน (far-far) แล้วย้อนกลับเข้า<b>ใกล้ขอบราว 2 mm</b> ตักตื้นที่ชั้น dermis บนกลับมาฝั่งแรก (near-near) ผูกปม · ทุกรูอยู่ใน<b>แนวเดียวกันตั้งฉากกับแผล</b> (ลายมือ \"เย็บ 1 ที = อยู่ที่เดิม\") · วงไกลรับแรงตึงและปิดช่องว่าง วงใกล้จัดขอบผิวให้ชนและนูน · ระยะวงไกลปรับตามความหนาผิว ผิวหนาที่ขาหรือหลังตักได้ไกลราว 1 cm ส่วนผิวบางที่หน้าตักใกล้กว่า · หัวใจคือวงใกล้ต้องตื้นและห่างขอบเท่ากันสองฝั่ง ขอบจึงยกขึ้นชนกันเป็นสันเล็กน้อย ซึ่งจะยุบลงเรียบเมื่อแผลหดตัว · สไลด์หน้า 11 ลายมือบนรูป <b>\"2 mm\"</b> · <b>\"1 cm\"</b>",
 wrong={"D":"10 cm ไกลเกินจริงมาก เกิดจากอ่าน 1 cm เป็น 10 cm · ไหมที่ตักห่างขอบขนาดนั้นจะรัดเนื้อเยื่อกว้างจนขาดเลือด และวงใกล้ 2 cm ก็ไม่ช่วยจัดขอบผิวให้ชนกัน · ไม่มีสถานการณ์ใดที่ vertical mattress ตักวงไกลห่างขอบแผล 10 cm เพราะเกินระยะที่ไหมผิวจะดึงขอบให้ชนกันได้"},
 trap="A และ C ใช้ตัวเลขชุดเดียวกับคำตอบแต่สลับตำแหน่งหรือหน่วย ส่วน D เปลี่ยน 1 cm เป็น 10 cm — จำว่า far = ไกล = ลึก = 1 cm · near = ใกล้ = ตื้น = 2 mm วงไกลต้องห่างขอบกว่าวงใกล้เสมอ",
 summary=[
  "Vertical mattress: <b>far ราว 1 cm · near ราว 2 mm</b> (ลายมือบนรูปหน้า 11)",
  "ทุกรูอยู่ใน<b>แนวเดียวกัน</b>ตั้งฉากกับแผล ผูกปมฝั่งเดียว (เย็บ 1 ที = อยู่ที่เดิม)",
  "ลำดับ: far-far ก่อน แล้วย้อน near-near — ไหมเริ่มและจบฝั่งเดียวกัน",
  "วงไกลลึก: รับแรงตึง ปิดช่องว่าง · วงใกล้ตื้น: จัดขอบผิวให้ชนและนูน",
  "<b>Better eversion</b> แลกกับ <b>stitch marks</b> (4 รู)",
  "ใช้เมื่อขอบมีแนวโน้มม้วนเข้า: ผิวหย่อน บริเวณข้อพับ หลังมือ ฝ่ามือ",
  "ตำราให้ระยะวงไกลราว 4–10 mm ตามความหนาของผิวและแผล"
 ])

S(43, wrong={"E":"ไม่มีไหมผิวชนิดใดที่ต้องตัดภายใน 24 ชั่วโมง เพราะแผลยังแทบไม่มีความแข็งแรง ต้องอาศัยไหมยึดหลายวัน (หน้าราว 5 วัน ลำตัว 7–10 วัน แขนขา 10–14 วัน) · ไม่มีสถานการณ์ใดที่ horizontal mattress ต้องตัดออกภายใน 24 ชั่วโมง"})

S(44,
 why="mattress มีสองแบบที่ให้ <b>better eversion</b>: vertical และ horizontal · <b>horizontal mattress</b> ตักขนานกับแผล ครอบช่วงแผลกว้างราว 1 cm ต่อเข็ม จึง<b>เย็บได้เร็วกว่า vertical</b> และกระจายแรงตึงได้ดี · ในแผลยาวทั้งแนว ถ้าใช้ vertical ทุกเข็มจะเสียเวลาและได้รูเข็ม 4 รูต่อเข็ม ส่วน horizontal หนึ่งเข็มครอบความยาวแผลได้มากกว่า จำนวนเข็มจึงน้อยลง · ข้อเสียคือรัดเนื้อเยื่อทั้งวง → ใช้ได้เมื่อผิวเลือดไหลเวียนดี ซึ่งในโจทย์คือชายหนุ่มแผลที่ต้นขาผิวปกติ · มักวาง horizontal เป็นระยะสลับกับ simple interrupted และผูกพอให้ขอบชน เพื่อให้เลือดยังผ่านระหว่างเข็มได้ · สไลด์หน้า 12 <b>Horizontal mattress</b> · ลายมือบนรูป <b>\"เย็บแบบนี้ ค.กว้าง ~1 cm = เร็วกว่า vertical mattress\"</b>",
 variants=[
  "หญิงแผลยาวที่ต้นแขนผิวดี ตึงปานกลาง → horizontal mattress เป็นระยะช่วยกระจายแรงตึง",
  "ชายแผลยาวที่หลังเย็บ horizontal mattress ผูกแน่นทุกเข็ม วันรุ่งขึ้นผิวในวงไหมคล้ำ → ผูกแน่นเกินจนรัดเลือด ตัดคลายบางเข็มแล้วเปลี่ยนเป็น simple",
  "ชายนักกีฬาแผลยาวที่หน้าแข้ง เลือดดี ขอบตึงเฉพาะช่วงกลางแผล → วาง horizontal mattress ช่วงกลางรับแรงตึง แล้วเย็บ simple ส่วนที่เหลือ"
 ])

S(45,
 why="ปลาย flap ที่ซีดบอกว่าเลือดที่มาเลี้ยงแย่อยู่แล้ว ร่วมกับผิวบางจาก steroid และอายุ · steroid ลดการสร้าง collagen และทำให้ผิวบาง ขอบ flap จึงทนการรัดได้น้อยกว่าปกติ · ปลาย flap เป็นส่วนที่ไกลจากฐานที่สุด เลือดมาถึงทาง subdermal plexus ทางเดียว · <b>horizontal mattress</b> รัดเนื้อเยื่อทั้งวงขนานขอบแผล → <b>ปิดกั้นเลือดที่จะวิ่งไปถึงขอบ flap</b> → ปลาย flap ตายได้ · ควรเลือกวิธีที่ไม่รัดฝั่ง flap: <b>half-buried</b> ที่ปลาย (ไหมวิ่งใน dermis ของ flap ไม่แทงผิว flap) · simple ผูกหลวม · ไหมชั้น dermis ไม่ตึง · และลดแรงตึงที่ flap · สไลด์หน้า 12 <b>Compromized blood flow</b> · ลายมือ <b>\"└ ตรงไหนที่ blood supply ไม่ดี = อย่าใช้\"</b>",
 variants=[
  "ชายหลังผ่าตัดยก flap ที่ขาซึ่งเคยฉายรังสี → เลี่ยงการเย็บรัดทั้งวงตามขอบ flap",
  "หญิงสูงอายุผิวฉีกที่แขนจากการกระแทก ผิวบางมาก → ปิดด้วย tape แทนการเย็บรัด",
  "หญิงสูบบุหรี่ นัดผ่าตัดยก flap ล่วงหน้า → ให้หยุดบุหรี่ก่อนผ่าตัดเพื่อลดปลาย flap ตาย",
  "ชายหลังยก flap ที่หลังมือ วันแรกปลาย flap คล้ำม่วง เลือดซึมสีดำ → เลือดดำคั่ง คลายไหมที่ตึงตามขอบก่อน"
 ])

S(46,
 interp="หญิงตัดไฝที่หน้าอก ต้องการไม่ให้มีรอยเข็มบนผิวเลย → ถามวิธีปิดชั้นผิวที่ดีที่สุด · ต้องรู้ว่าไหมผิวแบบใดไม่ผ่านผิวด้านบน และหน้าอกเป็นบริเวณที่แผลเป็นนูนง่ายจึงต้องคุมแรงตึงร่วมด้วย",
 why="<b>subcuticular</b> = ไหม 1 เส้นวิ่งในชั้น dermis ตรงรอยต่อ dermis-epidermis สลับตักซ้ายขวาไปตามแนวแผล เหมือนการสอยผ้า · ไหม<b>ไม่ผ่านผิวด้านบนเลย</b> จึง<b>ไม่มีรอยเข็ม</b> · ใช้ไหมละลายได้ไม่ต้องตัดไหม (นิยมกว่า มักเป็น monofilament เส้นเล็ก เช่น poliglecaprone) หรือไหมไม่ละลายแล้วดึงออกทั้งเส้นทีหลัง · ข้อจำกัดคือรับแรงตึงได้น้อยและต้องประกบขอบอย่างแม่น จึงต้องมีไหมชั้น dermis รับแรงก่อน และไม่เหมาะกับขอบแผลที่ขาดรุ่ยหรือปนเปื้อน · หน้าอกส่วนบนเป็นบริเวณที่แผลเป็นนูนและ keloid ง่าย จึงต้องลดแรงตึงและเลือกแนวแผลให้ดี · สไลด์หน้า 13 <b>Subcuticular suture</b> · <b>No stitch marks</b>",
 wrong={"B":"staple ผ่านผิวสองจุดต่อตัว ทิ้งรอยได้ ทั้งคุม eversion และประกบขอบอย่างละเอียดยาก จึงไม่เหมาะกับแผลที่เน้นความสวย · จะถูกถ้าชายแผลผ่าตัดยาวที่หนังศีรษะ ต้องการปิดเร็วที่สุด และผมจะปิดรอยเข็มอยู่แล้ว"},
 variants=[
  "หญิงผ่าตัดเต้านมแผลโค้งตามขอบลานนม → ปิดผิวด้วย subcuticular ไหมละลาย ไม่มีรอยเข็ม",
  "เด็กกลัวเข็ม ผ่าตัดถุงน้ำที่หลังมือ → subcuticular ไหมละลาย ไม่ต้องนัดมาตัดไหม",
  "หญิงแผลที่หน้าปิด subcuticular ด้วยไหม nylon → ดึงไหมออกทั้งเส้นทางปลายแผลด้านหนึ่งเมื่อครบกำหนด",
  "ชายแผลฉีกที่หน้าแข้ง ขอบขาดรุ่ยไม่เรียบ → subcuticular ไม่เหมาะเพราะต้องประกบขอบแม่น ใช้ simple interrupted แทน"
 ])

S(47,
 why="subcuticular ใช้ไหม<b>เส้นเดียวตลอดแผล</b> ตักในชั้น dermis ตรงรอยต่อ dermis-epidermis สลับซ้ายขวา · ถ้าแต่ละเข็ม<b>ตักไม่อยู่ระดับเดียวกัน</b> (บางเข็มตื้น บางเข็มลึก หรือฝั่งซ้ายขวาไม่ตรงกัน) เมื่อดึงไหมตึง ขอบแผลจะถูกดึงขึ้นลงไม่เท่ากัน → <b>ขอบเป็นคลื่น</b> · ส่วนที่บอกว่าไม่มีรอยเข็มและแผลบาง แสดงว่าเลือกวิธีและวางแนวแผลถูกแล้ว ปัญหาอยู่ที่ความสม่ำเสมอของการตัก · วิธีป้องกัน: ตักแต่ละเข็มที่ความลึกเดียวกันและยาวพอ ๆ กัน จุดเข้าเข็มฝั่งหนึ่งตรงกับจุดออกของอีกฝั่ง (ไม่ถอยหลัง) ดึงไหมให้ตึงสม่ำเสมอทั้งเส้น · ถ้าเห็นขอบเป็นคลื่นตั้งแต่ในห้องผ่าตัด ให้ปรับหรือเย็บใหม่ทันที · สไลด์หน้า 13 ลายมือ <b>\"ใช้ไหม 1 เส้นตลอดแผล → ต้องตักให้ได้ level เดียวตลอด ไม่งั้นจะเห็นเป็นคลื่นที่ขอบแผล\"</b>",
 wrong={
  "B":"ไหมละลายเป็นตัวเลือกที่นิยมสำหรับ subcuticular (ลายมือหน้า 13 เขียนว่านิยมกว่า) และไม่กำหนดรูปร่างขอบแผล ปัญหาของไหมละลายถ้ามีคือปลายไหมโผล่หรือปฏิกิริยาต่อไหม · ไม่มีสถานการณ์ใดที่การใช้ไหมละลายเองทำให้ขอบแผลเป็นคลื่น",
  "E":"แผลตามรอยย่นคอคือการวางแผลที่ถูกต้องตาม RSTL ช่วยให้แรงตึงขวางแผลน้อยและแผลเป็นจาง จึงเป็นเหตุที่แผลบาง ไม่ใช่ความผิดพลาด · ไม่มีสถานการณ์ใดที่การวางแผลตามรอยย่นทำให้ขอบแผลเป็นคลื่น"},
 summary=[
  "Subcuticular: เย็บ <b>dermoepidermal junction</b> · ใช้ไหม 1 เส้นตลอดแผล",
  "<b>ต้องตักให้ได้ level เดียวตลอด ไม่งั้นจะเห็นเป็นคลื่นที่ขอบแผล</b>",
  "Need precise approximation · No stitch marks",
  "ใช้ absorbable (นิยมกว่า) / non-absorbable แล้วมาดึงออกทีหลัง",
  "ป้องกันคลื่น: ตักลึกเท่ากัน ยาวพอ ๆ กัน จุดเข้าฝั่งหนึ่งตรงจุดออกอีกฝั่ง ดึงตึงสม่ำเสมอ",
  "ขอบเป็นคลื่น ≠ รอยเข็ม: คลื่นมาจากระดับการตัก ส่วนรอยเข็มมาจากไหมที่ผ่านผิวแล้วทิ้งไว้นาน",
  "แผลผ่าตัดไทรอยด์: วางตามรอยย่นคอ (RSTL แนวขวาง)"
 ])

S(48,
 interp="ชายแผลผ่าตัดสะอาดปิดชั้นผิวด้วย subcuticular → ถามระดับชั้นผิวหนังที่ไหมควรวิ่ง · ต้องรู้โครงสร้างชั้น (epidermis, dermis, ไขมัน, fascia) และว่าชั้นไหนเหนียวพอยึดไหมพร้อมทั้งอยู่ใกล้ผิวพอจะจัดขอบให้ชนกัน",
 why="subcuticular วิ่งในชั้น dermis ส่วนบน<b>ตรงรอยต่อ dermis กับ epidermis (dermoepidermal junction)</b> · ระดับนี้ dermis เหนียวพอให้ไหมยึดได้และอยู่ใกล้ผิวพอที่จะจัดขอบผิวให้ชนกันพอดี · ตื้นเกิน (ใน epidermis) ไหมฉีกและเห็นไหมใต้ผิว · ลึกเกิน (ในไขมัน) ขอบผิวไม่ถูกจัด แผลเหลื่อม · ในการปิดแผลเป็นชั้น ลำดับคือ fascia (ถ้ามี) → ไขมันเฉพาะเมื่อมีช่องว่าง → <b>deep dermal</b> ไหมละลายปมฝังลงล่างรับแรงตึงหลัก → subcuticular ที่ dermis บนจัดขอบผิว · ไหมต้องขนานกับผิวและอยู่ระดับเดียวกันตลอดแนว · รูปหน้า 13 แสดงไหมเป็นเส้นประใต้ผิว วงกลมน้ำเงินรอบระดับนี้ · สไลด์หน้า 13 ลายมือบนรูป <b>\"เย็บ dermoepidermal junction\"</b>",
 wrong={"D":"บนผิวเหนือแผลคือตำแหน่งของ skin tape หรือกาวทาผิว ไม่ใช่ทางวิ่งของไหม subcuticular ซึ่งต้องอยู่ใต้ผิวจึงไม่ทิ้งรอย · จะถูกถ้าเด็กแผลตื้นที่คาง ปิดด้วยแถบเทปวางบนผิวหลังเย็บชั้น dermis แล้ว เพื่อเสริมแรงยึดโดยไม่มีรอยเข็ม"},
 trap="A ฟังเหมือน \"ฝังใต้ผิว\" ตามคำว่า sub- จึงชวนเลือกชั้นไขมัน — แต่ subcuticular อยู่ใน dermis ตรงรอยต่อกับ epidermis · แยกโดยถามว่าชั้นไหนเหนียวพอยึดไหม และใกล้ผิวพอจะจัดขอบ = dermis ส่วนบน",
 summary=[
  "Subcuticular: เย็บ <b>dermoepidermal junction</b> (ลายมือบนรูปหน้า 13)",
  "ใช้ไหม 1 เส้นตลอดแผล ต้องตักให้ได้ level เดียวตลอด",
  "~ สอยผ้า ฝังไว้ใต้ผิวหนัง · ไม่ต้องตัดไหม · No stitch marks",
  "เหตุที่เลือก dermis บน: เหนียวพอยึดไหม + ใกล้ผิวพอจัดขอบผิวให้ชนพอดี",
  "ระดับชั้นอื่น: deep dermal = รับแรงตึง · ไขมัน = ปิดช่องว่าง · fascia = ผนังหน้าท้อง",
  "ลำดับปิดแผลเป็นชั้น: fascia → ไขมันเมื่อมีช่องว่าง → deep dermal ปมฝังลง → subcuticular"
 ],
 variants=[
  "ชายแผล subcuticular ที่ขา ขอบแผลห่างกันเป็นช่วง ๆ → ตักลึกเกินลงในไขมัน ขอบผิวไม่ถูกดึงให้ชน",
  "หญิงแผล subcuticular ไหมฉีกผ่านผิวขณะดึงให้ตึง → ตักตื้นเกินอยู่ใน epidermis ที่ไม่เหนียวพอยึดไหม",
  "ชายแผลผ่าตัดยาวที่หน้าท้อง ปิด fascia แล้ว ชั้นไขมันไม่มีช่องว่าง → ข้ามการเย็บไขมัน ไปเย็บ deep dermal แล้วปิดด้วย subcuticular"
 ])

S(49,
 interp="ชายแผลที่แขนมีปลายผิวรูปสามเหลี่ยมแคบ รูปแสดงวิธีเย็บที่ปลาย (half-buried หรือ corner stitch) → ถามจุดประสงค์หลักของวิธีนี้ · ต้องรู้ว่าปลายแหลมได้เลือดจากฐานทางเดียวจึงขาดเลือดง่าย",
 wrong={
  "B":"ไม่มีไหมผิวที่ตัดได้ในวันแรก เพราะแผลยังไม่มีความแข็งแรง และ half-buried ตัดไหมตามกำหนดปกติของบริเวณนั้น (แขนขาราว 10–14 วัน) · ไม่มีสถานการณ์ใดที่ half-buried ถูกเลือกเพื่อให้ตัดไหมได้ในวันแรก",
  "D":"การเย็บผิวที่ดีต้องการขอบนูน (eversion) ไม่ใช่ม้วนเข้า ขอบที่ม้วนเข้าจะหายเป็นร่องบุ๋ม และลายมือหน้า 14 ระบุว่า half-buried ช่วย control eversion · ไม่มีสถานการณ์ใดที่ตั้งใจทำให้ขอบปลาย flap ผิวม้วนเข้า"},
 trap="D ใช้คำว่า tip ตรงกับโจทย์ และ C ฟังเหมือนประโยชน์ของการฝังไหม — แต่ half-buried ตักแค่ dermis ของปลาย เป้าคือไม่แทงผิวปลายที่เลือดน้อย = รักษาเลือดที่ปลาย (Preserve blood supply at the tip)"
 )

S(50,
 interp="เด็กชายอายุ 17 ปีล้ม แผลรูปตัว V ที่คาง ปลายแคบและช้ำ → ถามวิธีเย็บที่เหมาะกับการยึดปลายแผล · ต้องรู้ว่าปลายแหลมที่ช้ำเลือดเลี้ยงไม่ดี และวิธีใดยึดปลายได้โดยไม่แทงผิวที่ปลาย",
 why="ปลาย V ที่<b>แคบและช้ำ</b> คือฝั่งที่เลือดเลี้ยงไม่ดีสองเท่า (มุมแหลม + tissue trauma) · <b>half-buried</b> ยึดปลายโดยไหมวิ่งในชั้น dermis ของปลาย ไม่แทงผิวที่ปลาย จึงไม่ตัดเลือดที่ขึ้นมาเลี้ยงผิว ทั้งยังดึงปลายลงตำแหน่งได้แม่นและให้ eversion · ส่วนแนวแผลที่เหลือเย็บ simple interrupted ตามปกติ · ปลายที่ตายชัด (ดำ ขาดรุ่ย) ให้เล็มออกเล็กน้อยก่อน แต่ที่หน้าเลือดเลี้ยงดี จึงเก็บเนื้อเยื่อที่ยังมีชีวิตไว้มากที่สุด · แผลที่คางจากการล้มต้องตรวจฟันและขากรรไกรด้วย เพราะแรงกระแทกคางส่งไปที่ข้อต่อขากรรไกร · สไลด์หน้า 14 ลายมือ <b>\"ใช้กับแผลรูป V / ปากฉลาม\"</b>",
 wrong={"E":"staple ยึดปลายแคบได้ไม่แม่น รัดผิวตรงปลายที่ช้ำ และทิ้งรอยที่หน้าซึ่งเป็นบริเวณที่ไม่ใช้ staple · จะถูกถ้าชายแผลยาวตรงที่หนังศีรษะ ต้องการปิดเร็ว ผมปิดรอย"},
 summary=[
  "<b>Half-buried</b>: ใช้กับแผลรูป V / ปากฉลาม · มุมแหลม · tissue trauma เยอะ",
  "Preserve blood supply at the tip · Minimize suture marks",
  "ไหมวิ่งใน dermis ของปลาย ไม่แทงผิวปลาย → ไม่ตัดเลือดที่ขึ้นมาเลี้ยง epidermis",
  "คล้าย horizontal mattress → control eversion",
  "แนวแผลที่เหลือเย็บ simple interrupted ตามปกติ",
  "ปลายช้ำ: เล็มเฉพาะเนื้อที่ตายชัด · ที่หน้าเลือดดี เก็บเนื้อเยื่อไว้มากที่สุด",
  "แผลที่คางจากการล้ม: ตรวจฟันและขากรรไกรร่วมด้วย"
 ],
 variants=[
  "หญิงแผลรูปดาวหลายแฉกที่หน้าผากจากกระจกบาด → half-buried ที่ปลายแต่ละแฉก",
  "ชายแผลตรงไม่มีปลายแหลมที่แขน → simple interrupted ไม่ต้อง half-buried",
  "เด็กล้มคางกระแทก มีแผลที่คางและเจ็บหน้าหูเวลาอ้าปาก → ตรวจหากระดูกขากรรไกรหักบริเวณข้อต่อ",
  "ชายแผลรูปตัว V ที่หลังมือ ปลายแหลมดำตายทั้งชิ้น → ตัดปลายที่ตายออกแล้วปิดเป็นแผลแนวตรง แทนการยึดปลายไว้"
 ])

